package cl.duoc.tienda.resena.service;
import cl.duoc.tienda.resena.dto.*; import cl.duoc.tienda.resena.model.*; import cl.duoc.tienda.resena.repository.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service;
@Service public class ResenaService { private static final Logger log=LoggerFactory.getLogger(ResenaService.class); private final ResenaRepository repo; public ResenaService(ResenaRepository r){repo=r;} public List<Resena> listar(){return repo.findAll();} public Resena buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Resena no encontrado: "+id));} public Resena guardar(ResenaRequest d){ Resena e=new Resena(d.usuarioId(), d.productoId(), d.calificacion(), d.comentario()); log.info("Guardando resena"); return repo.save(e);} public Resena actualizar(Long id,ResenaRequest d){buscar(id); Resena e=new Resena(d.usuarioId(), d.productoId(), d.calificacion(), d.comentario()); e.setId(id); return repo.save(e);} public void eliminar(Long id){buscar(id);repo.deleteById(id);log.info("Resena eliminado: {}",id);} }
